mapper.select:
select
a.algorithm_id,
a.algorithm_name,
a.alias_name,
a.describel,
a.algorithm_code,
a.analyse_type,
a.is_ai
from t_algorithm_info a
where 1 = 1
 and a.algorithm_id = #{algorithmId, jdbcType=BIGINT}
 and a.algorithm_name like concat('%',#{algorithmName,jdbcType=VARCHAR},'%')
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.describel = #{describel, jdbcType=VARCHAR}
 and a.algorithm_code = #{algorithmCode, jdbcType=VARCHAR}
 and a.analyse_type = #{analyseType, jdbcType=VARCHAR}
 and a.is_ai = #{isAi, jdbcType=INTEGER}

select
a.algorithm_id,
a.algorithm_name,
a.alias_name,
a.describel,
a.algorithm_code,
a.analyse_type,
a.is_ai,
b.dict_note
from t_algorithm_info a
LEFT JOIN t_dict_business b ON b.dict_code = a.analyse_type and (b.col_name = "analyse_type" or b.col_name ="defect_type")
where 1 = 1
 and a.algorithm_id = #{algorithmId, jdbcType=BIGINT}
 and a.algorithm_name like concat('%',#{algorithmName,jdbcType=VARCHAR},'%')
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.describel = #{describel, jdbcType=VARCHAR}
 and a.algorithm_code = #{algorithmCode, jdbcType=VARCHAR}
 and a.analyse_type = #{analyseType, jdbcType=VARCHAR}
 and a.is_ai = #{isAi, jdbcType=INTEGER}
 order by a.algorithm_id desc
